// MARK: - Tabs

/// The five tabs, in strip order: the three of the chrome cleanup — the
/// selected CLIP, the project's media, the document itself — the Transcript
/// (spec §11 TX-20) and the Assistant (AI-4). The raw value is the strip
/// index, so the order is API: the Transcript's arrival moved the Assistant
/// from 3 to 4, and every reader goes through `.assistant` or `allCases`.
///
/// It was six — Video, Audio, Text, Shape, Media, Document — and four of those
/// were the same thing viewed four ways: the selected clip. Collapsing them
/// took the whole tab-visibility policy with it (a disabled tab, a preferred
/// tab, a pin to defeat the preference), because a Clip tab that lists the
/// sections the SELECTION actually has is always the right tab for a clip.
/// `ClipPane.makeSections()` is where that decision moved to.
///
/// The four kind tests below — three of them outlived the tabs they were
/// written for — are now what decides which sections the Clip tab shows.
enum InspectorTab: Int, CaseIterable {
    case clip, media, document, transcript, assistant

    var title: String {
        switch self {
        case .clip: return "Clip"
        case .media: return "Media"
        case .document: return "Document"
        case .transcript: return "Transcript"
        case .assistant: return "Assistant"
        }
    }

    /// Whether the clip puts pixels on the canvas — and the test that keeps
    /// an audio-only clip out of the video sections.
    static func hasPixels(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        switch clip.source {
        case .text, .shape, .graphic, .nest, .adjustment:
            return true
        case .media, .still, .image:
            guard let media = snapshot.media(for: clip) else { return false }
            return media.hasVideo || media.kind == .image
        }
    }

    /// Whether the clip carries live audio: its media has a track AND this
    /// half of the clip is enabled (Detach Audio flips that, §6).
    ///
    /// A nest clip has no media of its own, so the media test cannot answer
    /// for it — and "no" would be the wrong answer, because a nest clip's own
    /// volume, mute and fades MULTIPLY every voice inside it
    /// (`core/src/audio.rs`: turning a nest down turns everything in it
    /// down). What it is asked instead is whether it has audio properties at
    /// all, which is the core's own answer to the same question: `nest` gives
    /// the clip an `AudioProps` exactly when something inside it can make a
    /// sound (`edit_nest.rs`) and `set_audio` errors with "clip N has no
    /// audio properties" when it did not. Walking the contents here would be
    /// a second copy of that rule, free to drift from the one the writes go
    /// through.
    static func hasAudio(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        guard clip.enabled.audio else { return false }
        if case .nest = clip.source { return clip.audio != nil }
        guard let media = snapshot.media(for: clip) else { return false }
        return media.hasAudio
    }

    /// Whether the clip's rectangle comes from a decoded source — the clips
    /// that get Crop, Colour and Corner Radius. Text and shape clips get
    /// Transform, Opacity and Shadow only (§4.3).
    static func hasSourcePixels(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        switch clip.source {
        case .media, .still, .image: return true
        case .text, .shape, .graphic, .nest, .adjustment: return false
        }
    }

    /// Whether the clip is an adjustment clip (spec §11 GR-6): it draws
    /// nothing of its own and grades what is behind it, so it gets Color and
    /// Clip and never Picture.
    static func isAdjustment(_ clip: ClipSnapshot) -> Bool {
        if case .adjustment = clip.source { return true }
        return false
    }
}
    /// `EditorViewController.refreshFromDocument`. `isLive` suppresses
    /// rebuilds: mid-gesture the values change but the shape does not.
    func refresh(isLive: Bool) {
        guard isViewLoaded else { return }
        refusalStrip.clearIfStale(document?.editedProject)
        binding.invalidate()
        let clips = selectedClips

        // Picking a clip in the timeline or on the canvas asks about THAT
        // clip, so the panel answers about it — one selection model, and the
        // panel is one of its three views (the timeline bar's block and the
        // canvas handles are the others).
        // Switched in place rather than through `select(_:)`: that one starts
        // a refresh of its own, and this one is already running — with
        // `isLive` in hand, which a nested call would drop.
        let ids = clips.map { $0.id }
        // A different clip and a different tab are the two things that make
        // the panel a different list, so they are the two that send it back to
        // the top; everything else leaves the user where they were reading.
        var toTop = false
        if ids != lastSelection {
            lastSelection = ids
            toTop = true
            (pane(for: .clip) as? ClipPane)?.forgetSubTab()
            if !clips.isEmpty, tab == .media || tab == .document {  // AI-14
                tab = .clip
                buildTabs()
            }
        }

        let pane = pane(for: tab)
        if showPane(pane) { toTop = true }
        let signature = pane.structureSignature
        // A rebuild replaces every control, so it must never happen under a
        // live gesture — the slider being dragged would vanish mid-drag.
        if signature != lastSignature, !isLive, document?.isLiveEditing != true {
            lastSignature = signature
            pane.rebuild()
            installPinned(pane.pinnedBlock)
        }
        pane.refresh()
                } ?? 0
            },
            onSelect: { [weak inspector] in inspector?.selectClipSubTab($0) })
        return ClipHeaderBlock(
            binding: binding, inspector: inspector, subTabs: strip,
            note: matteNote == nil ? nil : { [weak self] in self?.matteNote })
    }

    // MARK: - Sub-tabs

    /// The selection's tabs, in display order: Text or Shape first for those
    /// kinds, Picture for clips that draw unless an adjustment clip is among
    /// them (spec §11 GR-6: it draws nothing of its own), Color when every
    /// one of those has source pixels or is an adjustment clip (GR-2, GR-6:
    /// never text, shape, graphic, nest or an audio-only file's clip, which
    /// draws nothing), Sound for clips with audio, and Clip always, last.
    var subTabs: [ClipSubTab] {
        var tabs: [ClipSubTab] = []
        if textPane.allText { tabs.append(.text) }
        if shapePane.allShape { tabs.append(.shape) }
        if graphicPane.allGraphic { tabs.append(.graphic) }
        if !binding.videoClips.isEmpty && !videoPane.anyAdjustment { tabs.append(.picture) }
        if !binding.videoClips.isEmpty && videoPane.allGradable { tabs.append(.color) }
        if !binding.audioClips.isEmpty { tabs.append(.sound) }
        tabs.append(.clip)
        return tabs
    }

    /// The tab picked by hand while the selection has it, else the first.
    var activeSubTab: ClipSubTab {
        let tabs = subTabs
        if let chosen, tabs.contains(chosen) { return chosen }
        return tabs.first ?? .clip
    }

    /// Records a pick; triggers nothing (`selectClipSubTab` refreshes).
    func choose(_ tab: ClipSubTab) { chosen = tab }

    /// Back to the default tab; triggers nothing. The controller calls it
    /// when the selection's ids change.
    func forgetSubTab() {
        chosen = nil
        curveState.clear()
    }

    // MARK: - Kind → sections
            }
            if binding.isSingle, let clip = binding.primary,
               videoPane.overlap(before: clip) != nil {
                sections.append(videoPane.transitionSection(clip.id))
            }
            if hasPixels {
                sections.append(videoPane.motionSection())
            }
        }
        // A tab that would open as a column of shut headers opens its first
        // section with no stored preference instead. `expandByDefault` defers
        // to a section the user has closed themselves, so this is a default
        // and not an override — and it is offered to each section in TURN
        // because an id can be shared (`video.speed`, `clip.timing`), and a
        // group closed once elsewhere would otherwise leave the tab shut.
        if !sections.contains(where: { $0.isExpanded }) {
            for section in sections {
                if section.expandByDefault() { break }
            }
        }
        reveal.apply(sections, action: binding.selectedAction?.id, subTab: activeSubTab.rawValue)
        return sections
    }
}
import AppKit

/// One sub-tab of the Clip tab (spec §11 CI-5). The case order is the display
/// order: Text and Shape come first for those kinds, Clip is always last.
enum ClipSubTab: String, CaseIterable {
    case text, shape, graphic, picture, color, sound, clip

    var title: String {
        switch self {
        case .text: return "Text"
        case .shape: return "Shape"
        case .graphic: return "Graphic"
        case .picture: return "Picture"
        case .color: return "Color"
        case .sound: return "Sound"
        case .clip: return "Clip"
        }
    }

    /// The `◆N` badge (spec §11 CI-6): how many KEYS of an action's end patch
    /// this tab's sections write. Motion lives on Clip, so Picture counts the
    /// video keys without it; a shape's props are not animatable; Graphic
    /// counts the end's `graphic.props`, a key its module no longer declares
    /// included (CI-6 amended, G-34 (l)). Color counts `color`, one key
    /// however many of its thirteen the end names, and Picture no longer does
    /// (CI-6 amended by GR-2); for an all-adjustment selection (`adjustment`)
    /// it also counts `opacity`, the Adjustment section's Strength (GR-6). An
    /// end's `look` is Color's too, one key (GR-7), and so is its `wheels`,
    /// one key however many of its nine it names (GR-11), and its `curves`,
    /// one key however many channels it names (GR-12), and its `qualifier`,
    /// one key however many ranges it names (GR-13); Picture counts none of
    /// them. Clip also counts an end's `speed`, the Speed section's Rate (CI-6
    /// amended by SR-21).
    func keyedCount(in end: ActionPatch, adjustment: Bool = false) -> Int {
        switch self {
        case .text: return end.text?.dictionary.count ?? 0
        case .shape: return 0
        case .graphic: return end.graphic?.props.count ?? 0
        case .picture:
            let other: Set<String> = ["motion", "color", "look", "wheels", "curves", "qualifier"]
            return end.video?.dictionary.keys.filter { !other.contains($0) }.count ?? 0
        case .color:
            return (end.video?.color?.isEmpty == false ? 1 : 0)
                + (end.video?.dictionary["look"] != nil ? 1 : 0)
                + (end.video?.wheels?.isEmpty == false ? 1 : 0)
                + (end.video?.curves?.isEmpty == false ? 1 : 0)
                + (end.video?.qualifier?.isEmpty == false ? 1 : 0)
                + (adjustment && end.video?.dictionary["opacity"] != nil ? 1 : 0)
        case .sound: return end.audio?.dictionary.count ?? 0
        case .clip:
            return (end.video?.dictionary["motion"] == nil ? 0 : 1) + (end.speed == nil ? 0 : 1)
        }
    }
}

/// The strip of sub-tabs under the action lane: equal square cells whose 1 pt
/// borders collapse into one, the active cell in the selection fill with an
/// accent border, and a mint `◆N` after a label whose tab the selected action
/// keys. Built with its tabs and its active one, like `PanelTabsView`: a pick
/// goes out through `onSelect` and the pane is rebuilt with a new strip.

import AppKit

// MARK: - Selection header

/// The 44 pt block above the sections: the kind chip, the clip's name, and one
/// mono line of the facts a machine produced — how long it is, and where those
/// pixels came from.
///
/// It is the third view of the one selection model, the other two being the
/// timeline bar's block and the canvas's handles, so the chip and the kind word
/// come from `ClipKindStyle` and agree with them by construction. Drawn rather
/// than composed from controls — with ONE exception since format version 3:
/// for a single clip the name line is an `InspectorNameField`, because this
/// header is where the clip's OWN name is set and the only place it is cleared
/// (the strip's inline editor drops an empty commit — `TimelineView+Rename.swift`
/// says why). A multi-selection keeps the drawn "N clips selected". A label is
/// a 6 pt dot at the line's right end, the strip's dot, so the two views agree.
/// The field binds by clip ID and reads fresh through it (`timingSection`'s rule).
final class ClipSelectionHeaderView: NSView, OptionControl {
    static let height: CGFloat = 44
    /// The name line: 16 pt at y 8 drawn, a 20 pt field at y 6 typed into —
    /// both centred on y 16 — with the meta line under it. An
    /// `InspectorNameField` pins its own height at `DS.controlHeight`, more
    /// than a 44 pt band with a meta line can give, so the field's is
    /// re-pinned (`installNameField`).
    private static let nameTop: CGFloat = 8
    private static let nameHeight: CGFloat = 16
    private static let fieldTop: CGFloat = 6
    private static let fieldHeight: CGFloat = 20
    private static let metaTop: CGFloat = 27
    private static let dotSize: CGFloat = 6
    private static let dotGap: CGFloat = 6

    private let binding: InspectorBinding
    private var nameField: InspectorNameField?
    /// The field's right edge, pulled in by the dot's room while a label is set.
    private var nameTrailing: NSLayoutConstraint?

    init(binding: InspectorBinding) {
        self.binding = binding
        super.init(frame: .zero)
        wantsLayer = true
        // Decided once: the pane, header included, is rebuilt whenever the
        // selected ids change (`structureSignature`).
        if binding.isSingle, let clip = binding.primary {
            installNameField(for: clip.id)
        }
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ClipSelectionHeaderView does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: Self.height)
    }

    /// Redraws only when what it SAYS changed. The panel refreshes on every
    /// playhead tick when the selected clip has actions
    /// (`EditorViewController+Inspector.swift`), and re-laying two truncating
    /// strings across a 44 pt band thirty times a second for a value that moves
    /// once per click is work for nothing. The field's own `refresh` is as
    /// cheap, and skips itself while it is typed into.
    func refresh() {
        nameField?.refresh()
        let label = self.label
        let trailing = -(InspectorMetrics.inset + (label == nil ? 0 : Self.dotSize + Self.dotGap))
        if let constraint = nameTrailing, constraint.constant != trailing {
            constraint.constant = trailing
        }
        let next = [name, meta, label ?? ""]
        guard next != lastDrawn else { return }
        lastDrawn = next
        needsDisplay = true
    }

    private var lastDrawn: [String] = []

    // MARK: The name field

    /// The single-clip name line, typed into. It shows what the strip shows
    /// (`name(of:)` — own name or fallback), so what you read is what you
    /// edit, and commits the clip's OWN name: the trimmed text, or `null` for
    /// an emptied field, which is how a name goes back to the fallback.
    /// Emptying a field that already showed the fallback has nothing to
    /// clear: no op is sent (the core's refusal would only beep). Either way
    /// the field re-reads the model as the commit ends — `InspectorNameField`
    /// sets itself directly there, because its `refresh` is skipped while
    /// the field editor is attached, which it still is at that point.
    private func installNameField(for id: UInt32) {
        let binding = self.binding
        /// Read fresh through the captured id, never captured itself: a
        /// rename REPLACES the clip snapshot, and the header is refreshed.
        func clip() -> ClipSnapshot? { binding.snapshot.clip(id) }
        let field = InspectorNameField(
            read: { clip().map { binding.snapshot.name(of: $0) } ?? "" },
            write: { value in
                let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
                if trimmed.isEmpty, clip()?.name == nil { return }
                let patch = ClipPatch(name: .some(trimmed.isEmpty ? nil : trimmed))
                binding.apply("Rename Clip", [.setClip(clips: [id], patch: patch)])
            },
            enabled: { clip() != nil },
            onEdit: { binding.edited() })
        field.font = DS.sans(12, weight: .semibold)
        field.toolTip = "The clip's own name — empty it to go back to what the clip shows"
        // The field pins its own `DS.controlHeight` height; the one
        // constraint is re-pinned rather than fought with a second.
        for constraint in field.constraints
        where constraint.firstItem === field && constraint.firstAttribute == .height {
            constraint.constant = Self.fieldHeight
        }
        field.translatesAutoresizingMaskIntoConstraints = false
        addSubview(field)
        let trailing = field.trailingAnchor.constraint(
            equalTo: trailingAnchor, constant: -InspectorMetrics.inset)
        NSLayoutConstraint.activate([
            field.leadingAnchor.constraint(equalTo: leadingAnchor, constant: Self.nameLeft),
            field.topAnchor.constraint(equalTo: topAnchor, constant: Self.fieldTop),
            trailing,
        ])
        nameTrailing = trailing
        nameField = field
    }

    // MARK: What it says

    /// The chip's ink: the kind's tint, or the neutral one when the selection
    /// holds more than one kind and no single tint would be true.
    private var chipColor: NSColor {
        let clips = binding.clips
        guard let first = clips.first else { return DS.borderStrong }
        let tint = ClipKindStyle.tint(for: first, in: binding.snapshot)
        let mixed = clips.dropFirst().contains {
            ClipKindStyle.tint(for: $0, in: binding.snapshot) != tint
        }
        return mixed ? DS.borderStrong : tint
    }

    private var name: String {
        let clips = binding.clips
        guard let first = clips.first else { return "No selection" }
        guard clips.count == 1 else { return "\(clips.count) clips selected" }
        return binding.snapshot.name(of: first)
    }

    /// The label the selection agrees on — nil when the clips disagree or
    /// none has one, so the dot never claims a colour for a clip that has
    /// another. An unknown name draws in the neutral ink, as on the strip.
    private var label: String? {
        let clips = binding.clips
        guard let first = clips.first?.label, !first.isEmpty,
              clips.allSatisfy({ $0.label?.lowercased() == first.lowercased() })
        else { return nil }
        return first
    }

    /// The meta line: the kind word, the duration in the DOCUMENT's timecode
    /// (never the source's), and the source's own facts where there are any.
    private var meta: String {
        let clips = binding.clips
        let canvas = binding.canvas
        guard let first = clips.first else { return "" }
        guard clips.count == 1 else {
            let total = clips.reduce(Ticks(0)) { $0 + $1.duration }
            return ReelTime.format(total, fps: canvas.fps, frames: canvas.timecodeFrames)
                + " total"
        }
        var parts = [ClipKindStyle.name(for: first, in: binding.snapshot)]
        parts.append(
            ReelTime.format(first.duration, fps: canvas.fps, frames: canvas.timecodeFrames))
        if let size = binding.snapshot.sourceSize(of: first), size.width > 0, size.height > 0 {
            parts.append("\(Int(size.width))×\(Int(size.height))")
        }
        // The source's own rate, not the canvas's: it is the one fact here
        // that says whether this clip is being conformed.
        if let media = binding.snapshot.media(for: first), media.hasVideo, media.fps.double > 0 {
            parts.append("\(media.fps.displayName) fps")
        }
        return parts.joined(separator: " · ")
    }

    // MARK: Drawing

    /// Where the name line starts: after the chip and its gap.
    private static var nameLeft: CGFloat { InspectorMetrics.inset + 8 + 8 }

    override func draw(_ dirtyRect: NSRect) {
        DS.border.setFill()
        NSRect(x: 0, y: bounds.height - 1, width: bounds.width, height: 1).fill()

        let chip = NSRect(x: InspectorMetrics.inset, y: bounds.midY - 13, width: 8, height: 26)
        chipColor.setFill()
        chip.fill()

        let left = Self.nameLeft
        var nameRight = bounds.width - InspectorMetrics.inset
        if let label = label {
            // At the line's right end, centred on it, like the strip's.
            let dot = NSRect(
                x: nameRight - Self.dotSize,
                y: Self.nameTop + Self.nameHeight / 2 - Self.dotSize / 2,
                width: Self.dotSize, height: Self.dotSize)
            ClipLabel.color(named: label).setFill()
            NSBezierPath(ovalIn: dot).fill()
            nameRight = dot.minX - Self.dotGap
        }
        // The field paints its own line when there is one.
        if nameField == nil {
            let line = NSRect(
                x: left, y: Self.nameTop, width: max(nameRight - left, 10),
                height: Self.nameHeight)
            draw(name, in: line, font: DS.sans(12, weight: .semibold), color: DS.textStrong)
        }
        let width = max(bounds.width - left - InspectorMetrics.inset, 10)
        draw(meta, in: NSRect(x: left, y: Self.metaTop, width: width, height: 13),
             font: DS.mono(10), color: DS.textFaint)
    }

    /// One truncating line. `TimelineDraw.label` clips instead, which is right
    /// on a clip bar (the bar's edge says where it stopped) and wrong here,
    /// where a cut-off file name has nothing to say it was cut off.
    private func draw(_ text: String, in rect: NSRect, font: NSFont, color: NSColor) {
        guard !text.isEmpty, rect.width > 8 else { return }
        let paragraph = NSMutableParagraphStyle()
        paragraph.lineBreakMode = .byTruncatingTail
        text.draw(
            in: rect,
            withAttributes: [
                .font: font, .foregroundColor: color, .paragraphStyle: paragraph,
            ])
    }
}
import AppKit

// MARK: - Sections

/// One disclosure group: a header with the title, a right-aligned summary of
/// what the group currently says, an optional reset-to-default button, and the
/// rows. Collapsed state is per section id in `UserDefaults`, so a pane
/// rebuilt after every edit does not keep re-opening a group the user closed.
///
/// **The stored value records COLLAPSED, not expanded** — a section nobody has
/// touched has no stored value at all, which is what lets `defaultExpanded`
/// mean anything. Flipping that spelling would invert every saved panel.
final class InspectorSection: NSView {
    /// `UserDefaults` key prefix; the suffix is the section's stable id.
    static let collapsedKeyPrefix = "FrameJobInspectorSection."

    let id: String
    let title: String
    let header = InspectorSectionHeader()
    private let content = NSStackView()
    private(set) var isExpanded = true
    private let summary: (() -> String?)?
    /// An explicit "differs from its default" (spec §11 CI-9), for a section
    /// whose rows do not read the props or whose Reset writes fewer keys
    /// than its rows read; nil folds the rows' own defaults.
    private let differs: (() -> Bool)?
    /// The rows' marks, folded (road map 9 §5) at the end of `init` and on
    /// every `refresh()`.
    private(set) var marks = SectionMarks.empty
    /// "Actions don't animate this" — shown while every row that writes is ⊘.
    private var inertNote: InspectorNoteLabel?
    /// The header's click, after the preference is stored — and nothing else:
    /// `reveal()` and `expandByDefault()` never call it (`KeyedReveal`).
    var didToggle: ((InspectorSection) -> Void)?

    /// `summary` is a closure rather than a string because it is re-read on
    /// every `refresh()`: a collapsed section still has to tell the truth
